package com.mycompany.orbitaacademica.controller;

import com.mycompany.orbitaacademica.dao.TursoDAO;
import com.mycompany.orbitaacademica.service.PrivateFileService;
import jakarta.servlet.http.HttpSession;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.util.*;

@Controller
@RequestMapping("/estudiante/servicios")
public class StudentServicesController {
    private final TursoDAO dao; private final PrivateFileService files;
    public StudentServicesController(TursoDAO dao, PrivateFileService files){this.dao=dao;this.files=files;}
    private long user(HttpSession s){return Long.parseLong(String.valueOf(dao.consultar("SELECT id FROM Usuarios WHERE usuario=?",s.getAttribute("usuario")).get(0).get("id")));}
    private long student(HttpSession s){return Long.parseLong(String.valueOf(dao.consultar("SELECT id FROM Estudiantes WHERE usuario_id=?",user(s)).get(0).get("id")));}
    @GetMapping public String home(Model m,HttpSession s){long uid=user(s), sid=student(s);
        m.addAttribute("cuotas",dao.consultar("SELECT c.*, (SELECT pc.estado FROM PagosCuota pc WHERE pc.cuota_id=c.id AND pc.estudiante_id=? ) AS pago_estado FROM Cuotas c WHERE c.activa=1 ORDER BY c.periodo_mes DESC",sid));
        m.addAttribute("pagos",dao.consultar("SELECT p.*,c.concepto,c.periodo_mes,c.monto FROM PagosCuota p JOIN Cuotas c ON c.id=p.cuota_id WHERE p.estudiante_id=? ORDER BY p.id DESC",sid));
        m.addAttribute("documentos",dao.consultar("SELECT * FROM DocumentosEstudiante WHERE estudiante_id=? ORDER BY id DESC",sid));
        List<Map<String,Object>> tickets=dao.consultar("SELECT * FROM Tickets WHERE estudiante_id=? ORDER BY id DESC",sid);
        for(Map<String,Object> t:tickets)t.put("respuestas",dao.consultar("SELECT tr.*,u.usuario FROM TicketRespuestas tr JOIN Usuarios u ON u.id=tr.usuario_id WHERE tr.ticket_id=? ORDER BY tr.id",t.get("id")));
        m.addAttribute("tickets",tickets);
        m.addAttribute("notificaciones",dao.consultar("SELECT * FROM Notificaciones WHERE usuario_id=? ORDER BY id DESC LIMIT 20",uid));
        m.addAttribute("eventos",dao.consultar("SELECT * FROM EventosAcademicos WHERE estado='ACTIVO' ORDER BY fecha_inicio LIMIT 30"));
        m.addAttribute("evaluables",dao.consultar("SELECT m.id matricula_id,s.id seccion_id,d.id docente_id,d.nombre||' '||d.apellido docente,a.nombre asignatura FROM Matriculas m JOIN Secciones s ON s.id=m.seccion_id JOIN Docentes d ON d.id=s.docente_id JOIN Asignaturas a ON a.id=s.asignatura_id WHERE m.estudiante_id=? AND m.estado='ACTIVA' AND NOT EXISTS(SELECT 1 FROM EvaluacionesDocente ev WHERE ev.estudiante_id=m.estudiante_id AND ev.seccion_id=s.id)",sid));
        m.addAttribute("foto",dao.consultar("SELECT foto_url FROM PerfilArchivos WHERE usuario_id=?",uid));
        return "estudiante/servicios"; }
    @PostMapping("/documento") public String documento(@RequestParam String tipo,@RequestParam MultipartFile archivo,HttpSession s,RedirectAttributes ra){try{if(!List.of("TITULO_GRADUACION","PARTIDA_NACIMIENTO","DNI").contains(tipo))throw new IllegalArgumentException("Tipo de documento inválido.");String ref=files.save(archivo,"documentos","pdf");dao.ejecutarSQL("INSERT INTO DocumentosEstudiante(estudiante_id,tipo,archivo_url,nombre_archivo) VALUES(?,?,?,?)",student(s),tipo,ref,archivo.getOriginalFilename());notifyAdmins("Nuevo documento pendiente","Un estudiante cargó " + tipo + " para revisión.");ra.addFlashAttribute("ok","Documento enviado para revisión.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/estudiante/servicios";}
    @PostMapping("/pago") public String pago(@RequestParam long cuotaId,@RequestParam MultipartFile archivo,HttpSession s,RedirectAttributes ra){try{String ref=files.save(archivo,"pagos","pdf");long sid=student(s);dao.ejecutarSQL("INSERT INTO PagosCuota(cuota_id,estudiante_id,comprobante_url,nombre_archivo) VALUES(?,?,?,?)",cuotaId,sid,ref,archivo.getOriginalFilename());notifyAdmins("Comprobante de pago pendiente","Se recibió un comprobante de cuota.");ra.addFlashAttribute("ok","Comprobante enviado correctamente.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/estudiante/servicios";}
    @PostMapping("/oferta/{id}/espera") public String espera(@PathVariable long id,HttpSession s,RedirectAttributes ra){try{long sid=student(s);long exists=Long.parseLong(String.valueOf(dao.consultar("SELECT COUNT(*) n FROM Secciones WHERE id=? AND estado='ACTIVA'",id).get(0).get("n")));if(exists==0)throw new IllegalArgumentException("Sección no disponible.");long pos=Long.parseLong(String.valueOf(dao.consultar("SELECT COALESCE(MAX(posicion),0)+1 n FROM ListaEspera WHERE seccion_id=?",id).get(0).get("n")));dao.ejecutarSQL("INSERT INTO ListaEspera(estudiante_id,seccion_id,posicion) VALUES(?,?,?)",sid,id,pos);ra.addFlashAttribute("ok","Se agregó a la lista de espera.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/estudiante/oferta";}
    @PostMapping("/ticket") public String ticket(@RequestParam String asunto,@RequestParam String categoria,@RequestParam String descripcion,HttpSession s,RedirectAttributes ra){try{dao.ejecutarSQL("INSERT INTO Tickets(estudiante_id,asunto,categoria,descripcion) VALUES(?,?,?,?)",student(s),asunto,categoria,descripcion);notifyAdmins("Nuevo ticket de soporte",asunto);ra.addFlashAttribute("ok","Ticket creado.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/estudiante/servicios";}
    @PostMapping("/ticket/{id}/respuesta") public String responder(@PathVariable long id,@RequestParam String mensaje,HttpSession s,RedirectAttributes ra){try{long sid=student(s);long count=Long.parseLong(String.valueOf(dao.consultar("SELECT COUNT(*) n FROM Tickets WHERE id=? AND estudiante_id=?",id,sid).get(0).get("n")));if(count==0)throw new IllegalArgumentException("Ticket no encontrado.");dao.ejecutarSQL("INSERT INTO TicketRespuestas(ticket_id,usuario_id,mensaje) VALUES(?,?,?)",id,user(s),mensaje);dao.ejecutarSQL("UPDATE Tickets SET estado='ABIERTO',actualizado_en=CURRENT_TIMESTAMP WHERE id=?",id);ra.addFlashAttribute("ok","Respuesta enviada.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/estudiante/servicios";}
    @PostMapping("/evaluacion") public String evaluar(@RequestParam long seccionId,@RequestParam long docenteId,@RequestParam int puntuacion,@RequestParam(required=false) String comentario,HttpSession s,RedirectAttributes ra){try{long sid=student(s);long n=Long.parseLong(String.valueOf(dao.consultar("SELECT COUNT(*) n FROM Matriculas WHERE estudiante_id=? AND seccion_id=? AND estado='ACTIVA'",sid,seccionId).get(0).get("n")));if(n==0)throw new IllegalArgumentException("No puede evaluar una sección que no cursa.");dao.ejecutarSQL("INSERT INTO EvaluacionesDocente(estudiante_id,docente_id,seccion_id,puntuacion,comentario) VALUES(?,?,?,?,?)",sid,docenteId,seccionId,puntuacion,comentario);ra.addFlashAttribute("ok","Evaluación registrada. Sus respuestas serán confidenciales.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/estudiante/servicios";}
    @PostMapping("/foto") public String foto(@RequestParam MultipartFile archivo,HttpSession s,RedirectAttributes ra){try{String fname=archivo.getOriginalFilename()==null?"":archivo.getOriginalFilename().toLowerCase();String ext=fname.endsWith(".png")?"png":(fname.endsWith(".jpeg")?"jpeg":"jpg");String ref=files.save(archivo,"perfiles",ext);dao.ejecutarSQL("INSERT INTO PerfilArchivos(usuario_id,foto_url) VALUES(?,?) ON CONFLICT(usuario_id) DO UPDATE SET foto_url=excluded.foto_url,actualizado_en=CURRENT_TIMESTAMP",user(s),ref);ra.addFlashAttribute("ok","Fotografía actualizada.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/estudiante/servicios";}
    private void notifyAdmins(String title,String msg){for(Map<String,Object> a:dao.consultar("SELECT id FROM Usuarios WHERE UPPER(rol)='ADMIN'"))dao.ejecutarSQL("INSERT INTO Notificaciones(usuario_id,titulo,mensaje,enlace) VALUES(?,?,?,?)",a.get("id"),title,msg,"/admin/servicios");}
}
